head.script:
scwin.gVar = {
    "cMaxlength" : "",
    "cMaxByteLength" : "",
    "cRef" : "",
    "bReady" : false,
}



// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[secret > M > setValue]<br/>Secret 컴포넌트의 입력값을 설정합니다.",
    "validation" : [
        "value(필수) 파라미터로 Secret 컴포넌트의 입력값을 설정합니다.",
        "화면에는 입력값이 마스킹되어 표시됩니다.",
        "setValue() 메소드로 입력값 설정 시 maxlength, maxByteLength 속성의 제약을 받지 않습니다.",
        "ref 속성으로 DataCollection 을 바인딩한 경우 바인딩된 DataCollection 에도 입력값이 반영됩니다.",
        "setValue() 메소드로 입력값이 변경된 경우 onchange 이벤트는 발생하고, onviewchange 이벤트는 발생하지 않습니다.",
        "setValue() 메소드의 입력값은 '화면 값 반영 > 바인딩된 데이터 반영 > onchange 이벤트' 순서로 처리됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출 (gdm_ref 포함)
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // 바인딩 데이터 반영 시점 확인용 (validation 6 판정 수단)
    gdm_ref.bind("onmodelchange", scwin.gdm_ref_onmodelchange);

    // 정적 select1 기본값 설정 (자체 값 selectbox 는 value / 빈 항목은 인덱스)
    con_maxlength.setValue("3");
    con_maxByteLength.setSelectedIndex(0);
    con_ref.setValue("data:gdm_ref.key1");

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 생성 중 헬퍼의 초기값 설정으로 발생하는 이벤트는 출력하지 않음
    scwin.gVar["bReady"] = false;

    // 기존 컴포넌트 있으면 삭제
    if (typeof label1 !== 'undefined') {
        label1.remove();
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    $c.gcm.createLabel('label="[전제] target1 은 Secret 컴포넌트이며 생성 직후 초기값 secret (6자) 이 설정됩니다\n[절차] 위 조건 선택 -> Target 재생성 -> value 입력 -> setValue 클릭 (현재 값과 다른 value 를 입력해야 값이 변경됩니다)\n[확인] 결과창의 이벤트 줄 순서와 setValue 결과 줄 (getValue 값, 길이, Byte 수, 입력창 type, 바인딩 데이터 값)\n[참고] target1 에 직접 타이핑 후 포커스를 옮기면 onviewchange 가 발생하는 것과 대비됩니다"', '', 'label1');

    // 조건 설정
    scwin.gVar["cMaxlength"] = con_maxlength.getValue();
    scwin.gVar["cMaxByteLength"] = con_maxByteLength.getValue();
    scwin.gVar["cRef"] = con_ref.getValue();

    let properties = {
        maxlength : scwin.gVar["cMaxlength"],
        maxByteLength : scwin.gVar["cMaxByteLength"],
        ref : scwin.gVar["cRef"],
    }

    let cList = $c.gcm.createCList(properties);

    // comp 생성 함수 호출 (헬퍼가 생성 직후 setValue 로 초기값 secret 설정)
    await $c.gcm.createBasicSecret(cList, 'ev:onchange="scwin.target1_onchange" ev:onviewchange="scwin.target1_onviewchange"');

    scwin.gVar["bReady"] = true;
}



// 미설정 표기 변환
scwin.fn_disp = function (strValue) {
    return (strValue === "") ? "미설정" : strValue;
}



// setValue 실행 후 입력값/화면 표시/바인딩 데이터 확인 - validation 1, 2, 3, 4 판정 출력
scwin.btn_setValue_onclick = function (e) {
    let strParam = par_value.getValue();

    target1.setValue(strParam);

    let strValue = target1.getValue() || "";
    let strRtn = "setValue(" + strParam + ") -> getValue() : " + strValue + " (" + strValue.length + "자, " + WebSquare.util.getStringByteSize(strValue) + "byte)"
               + " / 입력창 type : " + target1.render.type
               + " / maxlength " + scwin.fn_disp(scwin.gVar["cMaxlength"]) + " / maxByteLength " + scwin.fn_disp(scwin.gVar["cMaxByteLength"]);

    if (scwin.gVar["cRef"] !== "")
        strRtn += " / gdm_ref.key1 : " + gdm_ref.get("key1");

    wf_body_bottom.getObj("scwin").setReturnValue(strRtn);
}



// 바인딩 데이터 반영 시점 - validation 4, 6 판정 출력 (이 시점에 화면 값이 이미 반영되어 있는지)
scwin.gdm_ref_onmodelchange = function (info) {
    if (!scwin.gVar["bReady"])
        return;

    wf_body_bottom.getObj("scwin").setReturnValue("▶ 바인딩 데이터 반영 : gdm_ref.key1 = " + info.newValue + " / 이 시점 화면 값 : " + target1.render.value);
}



// onchange 발생 - validation 5, 6 판정 출력 (이 시점에 화면 값과 바인딩 데이터가 이미 반영되어 있는지)
scwin.target1_onchange = function (info) {
    if (!scwin.gVar["bReady"])
        return;

    let strRtn = "▶ onchange 발생 / 이 시점 화면 값 : " + target1.render.value;

    if (scwin.gVar["cRef"] !== "")
        strRtn += " / 바인딩 데이터 값 : " + gdm_ref.get("key1");

    wf_body_bottom.getObj("scwin").setReturnValue(strRtn);
}



// onviewchange 발생 - validation 5 판정 출력 (setValue 로는 출력되지 않아야 함)
scwin.target1_onviewchange = function (info) {
    if (!scwin.gVar["bReady"])
        return;

    wf_body_bottom.getObj("scwin").setReturnValue("▶ onviewchange 발생");
}
